messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_order",
   "legacy_table": "db_pagos..pg_orden",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ord_numero"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ord_empresa"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ord_estado"
    },
    {
     "name": "paymentDate",
     "type": "timestamp(local)",
     "column": "payment_date",
     "legacy": "ord_fecha_pago"
    },
    {
     "name": "commission",
     "type": "decimal(19,4,signed)",
     "column": "commission",
     "legacy": "ord_comision"
    }
   ]
  },
  {
   "name": "CompanyTariff",
   "table": "company_tariff",
   "legacy_table": "db_admin..ad_tarifa_empresa",
   "key": [
    "companyId",
    "serviceCode"
   ],
   "fields": [
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "tar_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "tar_servicio"
    },
    {
     "name": "tariffValue",
     "type": "decimal(19,4,signed)",
     "column": "tariff_value",
     "legacy": "tar_valor"
    },
    {
     "name": "separateCharge",
     "type": "text(fixed,1,iso8859-1)",
     "column": "separate_charge",
     "legacy": "tar_separada"
    }
   ]
  },
  {
   "name": "ServiceCatalog",
   "table": "service_catalog",
   "legacy_table": "db_admin..ad_servicio",
   "key": [
    "serviceCode"
   ],
   "fields": [
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": "service_code",
     "legacy": "srv_codigo"
    },
    {
     "name": "defaultTariff",
     "type": "decimal(19,4,signed)",
     "column": "default_tariff",
     "legacy": "srv_tarifa"
    }
   ]
  },
  {
   "name": "Account",
   "table": "account",
   "legacy_table": "db_cuentas..ct_cuenta",
   "key": [
    "accountNumber",
    "accountType"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": "account_number",
     "legacy": "cta_numero"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "cta_tipo"
    },
    {
     "name": "balance",
     "type": "decimal(19,4,signed)",
     "column": "balance",
     "legacy": "cta_saldo"
    }
   ]
  },
  {
   "name": "DebitResult",
   "table": null,
   "legacy_table": null,
   "key": [],
   "fields": [
    {
     "name": "returnCode",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "return"
    },
    {
     "name": "movementSequence",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_secuencial"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "PaymentOrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndCompany",
     "description": "Reads the order (status) by number and company; empty when no row exists.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets status 'A', payment date and commission on the order. Returns the number of rows affected.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_orden"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "paymentDate",
       "type": "timestamp(local)",
       "column": null,
       "legacy": "@i_fecha_proceso"
      },
      {
       "name": "commission",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@w_comision"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "CompanyTariffRepository",
   "entity": "CompanyTariff",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCompanyAndService",
     "description": "Reads the tariff agreed for the company and service; empty when there is none.",
     "inputs": [
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "@i_empresa"
      },
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "CompanyTariff",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "ServiceRepository",
   "entity": "ServiceCatalog",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByCode",
     "description": "Reads the default tariff of the service; empty when the service does not exist.",
     "inputs": [
      {
       "name": "serviceCode",
       "type": "text(var,10,iso8859-1)",
       "column": null,
       "legacy": "@i_servicio"
      }
     ],
     "returns": "ServiceCatalog",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberAndType",
     "description": "Reads the account balance; empty when the account does not exist.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo_cuenta"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": "DebitResult",
   "legacy_program": "db_cuentas..sp_debito",
   "methods": [
    {
     "name": "debit",
     "description": "Debits the account (replaces the legacy debit procedure); returns its status and the movement sequence.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "text(fixed,10,iso8859-1)",
       "column": null,
       "legacy": "@i_cuenta"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "@i_tipo"
      },
      {
       "name": "amount",
       "type": "decimal(19,4,signed)",
       "column": null,
       "legacy": "@i_valor"
      },
      {
       "name": "reference",
       "type": "text(var,40,iso8859-1)",
       "column": null,
       "legacy": "@i_referencia"
      }
     ],
     "returns": "DebitResult",
     "legacy_output": null,
     "legacy_outputs": {
      "returnCode": "return",
      "movementSequence": "@o_secuencial"
     }
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Pays a payment order: validates account type and order, resolves tariff and commission, checks funds, debits the account (and the commission when charged separately), marks the order as paid and commits atomically.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005",
    "RULE-006",
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_orden"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@i_empresa"
    },
    {
     "name": "serviceCode",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "@i_servicio"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_tipo_cuenta"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "@i_cuenta"
    },
    {
     "name": "amount",
     "type": "decimal(19,4,signed)",
     "column": null,
     "legacy": "@i_valor"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "@i_canal"
    },
    {
     "name": "processDate",
     "type": "timestamp(local)",
     "column": null,
     "legacy": "@i_fecha_proceso"
    }
   ],
   "outputs": [
    {
     "name": "movementId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "@o_movimiento"
    },
    {
     "name": "message",
     "type": "text(var,120,iso8859-1)",
     "column": null,
     "legacy": "@o_mensaje"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "50001",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "50002",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "50003",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "50004",
     "message": "FONDOS INSUFICIENTES"
    },
    {
     "code": "DEBIT_FAILED",
     "legacy_code": "50005",
     "message": "ERROR EN DEBITO"
    },
    {
     "code": "COMMISSION_FAILED",
     "legacy_code": "50006",
     "message": "ERROR EN COMISION"
    },
    {
     "code": "ORDER_UPDATE_FAILED",
     "legacy_code": "50007",
     "message": "ERROR ACTUALIZANDO ORDEN"
    }
   ],
   "ports": [
    "PaymentOrderRepository",
    "CompanyTariffRepository",
    "ServiceRepository",
    "AccountRepository",
    "DebitGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/pay",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Data migrates to the target SQL Server database",
   "context": "The target keeps its data in SQL Server, which is not the engine of the legacy databases (db_pagos, db_admin, db_cuentas). The legacy tables cannot be accessed through the legacy qualified names.",
   "decision": "Use data_strategy migration: the order, company tariff, service and account tables move to the target database with snake_case table and column names (payment_order, company_tariff, service_catalog, account). Each entity keeps the legacy table and column in its traceability fields. The debit that sp_debito performed is provided by the DebitGateway port, implemented in the target on the migrated account data.",
   "consequences": "A data migration and a reconciliation of the four tables are needed before the cut-over. The debit logic of sp_debito must be reproduced in the target adapter and verified against the golden master. The service no longer depends on the legacy databases at runtime."
  },
  {
   "title": "Single transaction from the first debit to the commit",
   "context": "The legacy opens the transaction (line 108) after all validations and closes it at line 161. Three failure points roll back everything: the debit (119), the separate commission (136) and the order update (155).",
   "decision": "The PayOrder use case runs in one unit of work started at line 108 and committed at line 161. Each rollback point undoes the whole transaction and rejects with the business error DEBIT_FAILED, COMMISSION_FAILED or ORDER_UPDATE_FAILED. Reads and validations happen before the transaction starts. There are no savepoints.",
   "consequences": "If the commission debit or the order update fails, the first debit is undone. As the data now lives in one target database, the debit adapter and the order update take part in the same local transaction."
  },
  {
   "title": "Rejections are business errors, error plumbing is not translated",
   "context": "The legacy sets @w_error and @o_mensaje, then calls cobis..sp_cerror and returns @w_error on every rejection.",
   "decision": "Each rejection is a business error with a stable code, carrying the legacy code (50001 to 50007) and the legacy message. sp_cerror is treated as infrastructure and is not called. The success message 'PAGO REALIZADO' is returned in the message output.",
   "consequences": "Callers get an HTTP error with the code instead of a return status. The outputs of a rejection are the message and the legacy code."
  },
  {
   "title": "Preserve the legacy NULL semantics and arithmetic",
   "context": "In the legacy a NULL balance (missing account) makes the funds comparison false, so the check passes and the debit decides. A NULL tariff becomes 0. A company tariff row with a NULL separate flag falls into the 'add commission' branch. The WEB commission is round(tariff/2, 2) on money values.",
   "decision": "The funds check is only evaluated when a balance exists. A missing or NULL tariff is 0. Only the flag 'S' means the commission is charged separately. Amounts are BigDecimal with scale 4, and the WEB commission is rounded to 2 decimals with HALF_UP.",
   "consequences": "The behaviour of edge cases equals the legacy. Missing accounts are rejected by the debit (DEBIT_FAILED), not by the funds check."
  },
  {
   "title": "Failure of the debit call includes technical errors",
   "context": "The legacy rejects the first debit when the debit procedure returns non-zero or @@error is non-zero.",
   "decision": "A non-zero return code or an exception from DebitGateway.debit for the payment debit is mapped to DEBIT_FAILED after rolling back. The commission debit is rejected only on a non-zero return code (COMMISSION_FAILED), as in the legacy.",
   "consequences": "Both outcomes of the first debit give the same error to the caller."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Account type must be CTE, AHO or VIR",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order is only accepted for account types CTE, AHO or VIR. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is allowed\n  Given the account type is 'AHO'\n  When the payment order is validated\n  Then no error is set for the account type",
   "Scenario: Account type is not allowed\n  Given the account type is 'PRE'\n  When the payment order is validated\n  Then the error code is 50001\n  And the message is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Payment order must be pending to be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "An order can only proceed when its status is 'P' (pending). Any other status is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "The status ord_estado of the order identified by @i_orden and @i_empresa in db_pagos..pg_orden is not 'P'.",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'. The slice does not show what happens after the error is set.",
  "inputs": [
   {
    "name": "@i_orden",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order is pending\n  Given order 100 of company 1 has status 'P'\n  When the payment procedure checks the order\n  Then no error is raised by this check",
   "Scenario: Order is not pending\n  Given order 100 of company 1 has status 'X'\n  When the payment procedure checks the order\n  Then @w_error is 50003\n  And @o_mensaje is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 54
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 56,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment rejected when order does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "If the lookup of the order to be paid returns no rows, the payment is rejected with error code 50002 and the message 'ORDEN NO EXISTE'.",
  "condition": "@@rowcount = 0 after the preceding order lookup",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the lookup of the order to pay returns 0 rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the lookup of the order to pay returns 1 row\n  When the payment procedure evaluates the result\n  Then error 50002 is not set by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Commission tariff lookup: company-specific tariff overrides service default",
  "category": "calculation",
  "priority": "P0",
  "statement": "The base tariff for a payment is the one agreed for the company and service. If the company has no specific tariff for that service, the service's default tariff is used and the commission is not charged separately ('N'). If no tariff can be determined, it is zero.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise use ad_servicio.srv_codigo = @i_servicio; if the resulting tariff is NULL.",
  "action": "With a company row: tariff = tar_valor and separate-charge flag = tar_separada. Without one (@@rowcount = 0): tariff = srv_tarifa and flag = 'N'. If the tariff is NULL it becomes 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company tariff exists\nGiven company 10 has a tariff of 2.0000 with separate charge 'S' for service 'LUZ'\nWhen the tariff is resolved\nThen the tariff is 2.0000 and the separate-charge flag is 'S'",
   "Scenario: Fall back to service tariff\nGiven company 10 has no tariff row for service 'AGUA' and the service tariff is 1.5000\nWhen the tariff is resolved\nThen the tariff is 1.5000 and the separate-charge flag is 'N'",
   "Scenario: No tariff defined\nGiven the resolved tariff is NULL\nWhen the tariff is resolved\nThen the tariff is 0"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 62,
    "line_end": 66
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 68,
    "line_end": 68
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 70,
    "line_end": 72
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 76,
    "line_end": 77
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Comisión por canal y servicio NOMINA",
  "category": "calculation",
  "priority": "P0",
