        public Account? Account { get; set; }
        public List<(string? Number, string? Type)> Finds { get; } = new();

        public Account? FindByNumberAndType(string? accountNumber, string? accountType)
        {
            log.Add("find-account");
            Finds.Add((accountNumber, accountType));
            return Account;
        }
    }

    private sealed class FakeDebit(List<string> log) : DebitGateway
    {
        public List<DebitCall> Calls { get; } = new();
        public Func<int, DebitCall, DebitResult?>? Handler { get; set; }

        public DebitResult? Debit(string? accountNumber, string? accountType, decimal? amount, string? reference)
        {
            log.Add("debit:" + reference);
            var call = new DebitCall(accountNumber, accountType, amount, reference);
            Calls.Add(call);
            var index = Calls.Count; // 1-based
            if (Handler != null) return Handler(index, call);
            return new DebitResult(0, 1000 + index);
        }
    }

    private sealed class Fixture
    {
        public List<string> Log { get; } = new();
        public FakeOrders Orders { get; }
        public FakeTariffs Tariffs { get; }
        public FakeServices Services { get; }
        public FakeAccounts Accounts { get; }
        public FakeDebit Debits { get; }
        public PayOrderService Service { get; }

        public Fixture(decimal? balance = 1000m)
        {
            Orders = new FakeOrders(Log) { Order = new PaymentOrder(100, 1, "P", null, null) };
            Tariffs = new FakeTariffs(Log);
            Services = new FakeServices(Log);
            Accounts = new FakeAccounts(Log)
            {
                Account = new Account("1234567890", "AHO", balance)
            };
            Debits = new FakeDebit(Log);
            Service = new PayOrderService(Orders, Tariffs, Services, Accounts, Debits);
        }
    }

    private static readonly DateTime ProcessDate = new(2024, 5, 31);

    private static PayOrderRequest Request(
        int? orderNumber = 100,
        int? companyId = 1,
        string? serviceCode = "AGUA",
        string? accountType = "AHO",
