using Bank.Payments.Adapters.In.Rest;
using Bank.Payments.Domain.Error;
using Bank.Payments.Domain.Port;

namespace Bank.Payments.Application;

public sealed class PayOrderService(
    PaymentOrderRepository orders,
    CompanyTariffRepository tariffs,
    ServiceRepository services,
    AccountRepository accounts,
    DebitGateway debits)
{
    // Legacy comparisons ignore trailing spaces (CHAR padding); a NULL operand never gives true.
    private static bool Eq(string? value, string literal)
        => value != null && value.TrimEnd(' ') == literal;

    private static bool Ne(string? value, string literal)
        => value != null && value.TrimEnd(' ') != literal;

    public PayOrderResponse Execute(PayOrderRequest request)
    {
        // @i_canal default 'WEB' (applied when the parameter is not supplied)
        var channel = request.Channel ?? "WEB";

        // RULE-001: NULL NOT IN (...) is unknown, so only a non-null type outside the list rejects
        if (request.AccountType != null
            && Ne(request.AccountType, "CTE")
            && Ne(request.AccountType, "AHO")
            && Ne(request.AccountType, "VIR"))
        {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003 / RULE-002
        var order = orders.FindByNumberAndCompany(request.OrderNumber, request.CompanyId);
        if (order == null)
        {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        // NULL status: <> 'P' is not true, the procedure continues
        if (Ne(order.Status, "P"))
        {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004
        decimal? tariff = null;
        string? separate = null;
        var companyTariff = tariffs.FindByCompanyAndService(request.CompanyId, request.ServiceCode);
        if (companyTariff != null)
        {
            tariff = companyTariff.TariffValue;
            separate = companyTariff.SeparateCharge;
        }
        else
        {
            var service = services.FindByCode(request.ServiceCode);
            if (service != null)
            {
                tariff = service.DefaultTariff;
                separate = "N";
            }
            // no row: variables keep their previous (NULL) value
        }

        if (tariff == null)
        {
            tariff = 0m;
        }

        // RULE-005
        decimal? commission;
        if (Eq(channel, "WEB"))
        {
            commission = Math.Round(tariff.Value / 2m, 2, MidpointRounding.AwayFromZero);
        }
        else
        {
            commission = tariff;
        }

        if (Eq(request.ServiceCode, "NOMINA"))
        {
            commission = 0m;
        }

        // RULE-006
        decimal? total;
        if (Eq(separate, "S"))
        {
            total = request.Amount;
        }
        else
        {
            total = request.Amount + commission;
        }

        // RULE-007: a missing account gives a NULL balance, so the comparison is not true
        var account = accounts.FindByNumberAndType(request.AccountNumber, request.AccountType);
        decimal? balance = account?.Balance;

        var isVir = Eq(request.AccountType, "VIR");
        var isNotVir = Ne(request.AccountType, "VIR");
        if ((isVir && balance < total)
            || (isNotVir && balance + 100.00m < total))
        {
            throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
        }

        // RULE-008
        Bank.Payments.Domain.Model.DebitResult? debit;
        try
        {
            debit = debits.Debit(request.AccountNumber, request.AccountType, total, "PAGO ORDEN");
        }
        catch (Exception)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        if (debit == null || debit.ReturnCode != 0)
        {
            throw new BusinessError("DEBIT_FAILED", "50005", "ERROR EN DEBITO");
        }

        var movementId = debit.MovementSequence;

        // RULE-009 / RULE-010
        if (Eq(separate, "S") && commission > 0)
        {
            var commissionDebit = debits.Debit(request.AccountNumber, request.AccountType, commission, "COMISION PAGO");
            if (commissionDebit == null || commissionDebit.ReturnCode != 0)
            {
                throw new BusinessError("COMMISSION_FAILED", "50006", "ERROR EN COMISION");
            }
        }

        // RULE-011 / RULE-012
        int rows;
        try
        {
            rows = orders.MarkPaid(request.OrderNumber, request.CompanyId, request.ProcessDate, commission);
        }
        catch (Exception)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        if (rows == 0)
        {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-013
        return new PayOrderResponse(movementId, "PAGO REALIZADO");
    }
}
